head.script:
scwin.onpageload = function() {

};

scwin.trigger1_onclick = function(e) {
    var cnt = categoryGen.getLength()
    for (var i = 0; i < cnt; i++) {
        var c1 = categoryGen.getChild(i, "t1");
        var c2 = categoryGen.getChild(i, "t2");
        var c3 = categoryGen.getChild(i, "t3");
        var c4 = categoryGen.getChild(i, "t4");
        var c5 = categoryGen.getChild(i, "t5");
        c1.setStyle("background-color", "");
        c2.setStyle("background-color", "");
        c3.setStyle("background-color", "");
        c4.setStyle("background-color", "");
        c5.setStyle("background-color", "");
    }

    var idx = categoryGen.insertChild(0);
    var x1 = categoryGen.getChild(idx, "t1");
    var x2 = categoryGen.getChild(idx, "t2");
    var x3 = categoryGen.getChild(idx, "t3");
    var x4 = categoryGen.getChild(idx, "t4");
    var x5 = categoryGen.getChild(idx, "t5");
    x1.setStyle("background-color", "yellow");
    x2.setStyle("background-color", "yellow");
    x3.setStyle("background-color", "yellow");
    x4.setStyle("background-color", "yellow");
    x5.setStyle("background-color", "yellow");
};

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('categoryGen').children[0].innerText == '1';
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand('pause', '500');
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand('pause', '500');
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
